package org.apache.commons.math.optimization.general;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxEvaluationsExceededException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.DifferentiableMultivariateVectorialFunction;
import org.apache.commons.math.analysis.MultivariateMatrixFunction;
import org.apache.commons.math.exception.LocalizedFormats;
import org.apache.commons.math.linear.InvalidMatrixException;
import org.apache.commons.math.linear.LUDecompositionImpl;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.optimization.DifferentiableMultivariateVectorialOptimizer;
import org.apache.commons.math.optimization.OptimizationException;
import org.apache.commons.math.optimization.SimpleVectorialValueChecker;
import org.apache.commons.math.optimization.VectorialConvergenceChecker;
import org.apache.commons.math.optimization.VectorialPointValuePair;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for AbstractLeastSquaresOptimizer.getRMS()
 */
public class AbstractLeastSquaresOptimizer_getRMS_TriageGen4Test {

    private TestableOptimizer optimizer;

    /**
     * Concrete implementation of the abstract class to allow testing.
     */
    private static class TestableOptimizer extends AbstractLeastSquaresOptimizer {
        protected TestableOptimizer() {
            super();
        }

        @Override
        protected VectorialPointValuePair doOptimize() {
            return null;
        }

        // Helper methods to inject protected/private fields for testing purposes
        public void setInternalState(double[] residuals, double[] weights, int rows) {
            try {
                Field residualsField = AbstractLeastSquaresOptimizer.class.getDeclaredField("residuals");
                residualsField.setAccessible(true);
                residualsField.set(this, residuals);

                Field weightsField = AbstractLeastSquaresOptimizer.class.getDeclaredField("residualsWeights");
                weightsField.setAccessible(true);
                weightsField.set(this, weights);

                Field rowsField = AbstractLeastSquaresOptimizer.class.getDeclaredField("rows");
                rowsField.setAccessible(true);
                rowsField.set(this, rows);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    @Before
    public void setUp() {
        optimizer = new TestableOptimizer();
    }

    @Test
    public void testGetRMS_StandardCase() {
        // residuals = [3.0, 4.0], weights = [1.0, 1.0], rows = 2
        // criterion = (3^2 * 1) + (4^2 * 1) = 9 + 16 = 25
        // RMS = sqrt(25 / 2) = sqrt(12.5) ≈ 3.5355339
        double[] residuals = {3.0, 4.0};
        double[] weights = {1.0, 1.0};
        optimizer.setInternalState(residuals, weights, 2);

        double expected = Math.sqrt(25.0 / 2.0);
        Assert.assertEquals(expected, optimizer.getRMS(), 1e-10);
    }

    @Test
    public void testGetRMS_WithWeights() {
        // residuals = [2.0, 2.0], weights = [0.5, 2.0], rows = 2
        // criterion = (2^2 * 0.5) + (2^2 * 2.0) = (4 * 0.5) + (4 * 2.0) = 2 + 8 = 10
        // RMS = sqrt(10 / 2) = sqrt(5) ≈ 2.2360679
        double[] residuals = {2.0, 2.0};
        double[] weights = {0.5, 2.0};
        optimizer.setInternalState(residuals, weights, 2);

        double expected = Math.sqrt(5.0);
        Assert.assertEquals(expected, optimizer.getRMS(), 1e-10);
    }

    @Test
    public void testGetRMS_ZeroResiduals() {
        double[] residuals = {0.0, 0.0, 0.0};
        double[] weights = {1.0, 1.0, 1.0};
        optimizer.setInternalState(residuals, weights, 3);

        Assert.assertEquals(0.0, optimizer.getRMS(), 1e-10);
    }

    @Test
    public void testGetRMS_SingleElement() {
        double[] residuals = {5.0};
        double[] weights = {1.0};
        optimizer.setInternalState(residuals, weights, 1);

        // sqrt(5^2 * 1 / 1) = 5
        Assert.assertEquals(5.0, optimizer.getRMS(), 1e-10);
    }

    @Test
    public void testGetRMS_EmptyRows() {
        // If rows is 0, criterion is 0, result is sqrt(0/0) which is NaN
        double[] residuals = {};
        double[] weights = {};
        optimizer.setInternalState(residuals, weights, 0);

        Assert.assertTrue(Double.isNaN(optimizer.getRMS()));
    }

    @Test
    public void testGetRMS_AllWeightsZero() {
        double[] residuals = {10.0, 20.0};
        double[] weights = {0.0, 0.0};
        optimizer.setInternalState(residuals, weights, 2);

        Assert.assertEquals(0.0, optimizer.getRMS(), 1e-10);
    }
}
